import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

export const GeneratedShot = (props: any) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const wordAt = (index: number, fallback: number) => {
    const cue = cues.find((item: any) => item.wordIndex === index || item.index === index) || cues[index];
    return typeof cue?.startFrame === "number" ? cue.startFrame : fallback;
  };
  const limit = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
  const ease = Easing.inOut(Easing.cubic);
  const ramp = (start: number, end: number) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { ...limit, easing: ease });
  const appear = (start: number) => frame < start ? 0 : spring({ frame: frame - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });

  const pushStart = wordAt(2, 32);
  const pushEnd = wordAt(7, 121) + 1;
  const fanCue = wordAt(6, 103);
  const coolCue = wordAt(9, 157);
  const regionCue = wordAt(11, 192);
  const suddenCue = wordAt(13, 228);
  const stopCue = wordAt(14, 246);
  const pullStart = wordAt(15, 264);
  const pullEnd = wordAt(19, 364) + 1;
  const driftEnd = Math.min(durationInFrames - 1, wordAt(22, 422) + 20);
  const zoom = 1 + 0.22 * ramp(pushStart, pushEnd) - 0.22 * ramp(pullStart, pullEnd);
  const panY = 40 * ramp(pushStart, pushEnd) - 40 * ramp(pullStart, pullEnd);
  const panX = 18 * ramp(pullEnd, Math.max(pullEnd + 1, driftEnd));

  const shellEntry = appear(0);
  const cardEntry = appear(6);
  const laneEntry = appear(10);
  const waterEntry = appear(15);
  const titleEntry = appear(2);
  const cooling = ramp(coolCue, coolCue + 18);
  const regionEntry = appear(regionCue);
  const focusEntry = appear(fanCue);
  const stoppedEntry = appear(stopCue);
  const stopProgress = ramp(suddenCue, stopCue);
  const windStrength = 1 - stopProgress;
  const statusChange = ramp(stopCue, stopCue + 8);
  const brakeDuration = Math.max(1, stopCue - suddenCue);
  const brakeTime = Math.max(0, Math.min(frame - suddenCue, brakeDuration));
  const travelTime = frame < suddenCue ? frame : suddenCue + brakeTime - (brakeTime * brakeTime) / (2 * brakeDuration);
  const rotation = -16 - travelTime * 2.45;
  const focusOpacity = Math.min(1, focusEntry) * (frame < suddenCue ? 0.72 : 0.95);
  const focusColor = frame < stopCue ? "#246BFD" : "#F26B58";
  const statusColor = frame < stopCue ? "#246BFD" : "#F26B58";
  const sheenOpacity = 0.14 + 0.045 * Math.sin(frame * 0.032);
  const mono = "'IBM Plex Mono', monospace";
  const inter = "Inter, sans-serif";
  const ink = "#142B3C";
  const blue = "#246BFD";
  const teal = "#168FAD";

  return (
    <AbsoluteFill style={{ overflow: "hidden", background: "#F4F6F2", fontFamily: inter, color: ink }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920) / 2, top: (height - 1080) / 2, overflow: "hidden", borderRadius: 24, background: "linear-gradient(150deg, #F4F6F2 0%, #F9FCFC 36%, #E4EEF4 72%, #EDF4EF 100%)" }}>
        <AbsoluteFill style={{ opacity: 0.36 }}>
          <mg.GridBackground mode="light" gridSize={48} />
        </AbsoluteFill>
        <AbsoluteFill style={{ borderRadius: 24, background: "radial-gradient(ellipse at 72% 27%, rgba(36,107,253,0.16) 0%, transparent 59%), radial-gradient(ellipse at 25% 77%, rgba(22,143,173,0.13) 0%, transparent 60%)", transform: "translateX(" + interpolate(frame, [0, 456], [0, 14], limit) + "px)" }} />

        <div style={{ position: "absolute", left: 120, top: 88, zIndex: 5, opacity: Math.min(1, titleEntry), transform: "translateY(" + (1 - titleEntry) * 10 + "px)" }}>
          <div style={{ fontFamily: "Manrope, Inter, sans-serif", fontSize: 52, fontWeight: 600, lineHeight: 1.12, letterSpacing: -1.7, whiteSpace: "nowrap" }}>The Pacific's natural fan.</div>
          <div style={{ marginTop: 12, display: "flex", alignItems: "center", gap: 13, fontSize: 25, fontWeight: 500, lineHeight: 1.1, letterSpacing: 2.2 }}>
            <span style={{ display: "inline-block", width: 9, height: 9, borderRadius: 9999, background: blue, boxShadow: "0 0 16px rgba(36,107,253,0.35)" }} />
            COOLING MECHANISM · FAN METAPHOR
          </div>
        </div>

        <div style={{ position: "absolute", left: 100, top: 198, width: 1720, height: 786, boxSizing: "border-box", overflow: "hidden", borderRadius: 24, background: "rgba(255,255,255,0.72)", backdropFilter: "blur(14px)", border: "1px solid rgba(36,107,253,0.16)", boxShadow: "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(20,43,60,0.08)", opacity: Math.min(1, shellEntry), transform: "translateY(" + (1 - shellEntry) * 8 + "px)" }}>
          <div style={{ position: "absolute", inset: 0, borderRadius: 24, background: "radial-gradient(ellipse at 50% 35%, rgba(36,107,253,0.10), transparent 63%), radial-gradient(ellipse at 50% 93%, rgba(22,143,173,0.11), transparent 62%)" }} />
          <div style={{ position: "absolute", left: 38, top: 31, fontSize: 28, fontWeight: 600, letterSpacing: -0.5 }}>Eastern Pacific</div>
          <div style={{ position: "absolute", right: 38, top: 35, display: "flex", alignItems: "center", gap: 10, color: "#476474", fontSize: 20, fontFamily: mono, letterSpacing: 1.7 }}>
            <span style={{ width: 7, height: 7, borderRadius: 9999, background: teal }} />
            CONCEPTUAL VIEW
          </div>
          <div style={{ position: "absolute", left: 58, top: 268, display: "flex", flexDirection: "column", gap: 11 }}>
            <span style={{ fontFamily: mono, color: blue, fontSize: 21 }}>←</span>
            <span style={{ fontSize: 28, fontWeight: 500, letterSpacing: 4 }}>WEST</span>
          </div>
          <div style={{ position: "absolute", right: 58, top: 268, display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 11 }}>
            <span style={{ fontFamily: mono, color: blue, fontSize: 21 }}>←</span>
            <span style={{ fontSize: 28, fontWeight: 500, letterSpacing: 4 }}>EAST</span>
          </div>
        </div>

        <div style={{ opacity: 0.5 }}>
          <mg.Marker x={143} y={925} variant="cross" color={blue} />
          <mg.Marker x={1774} y={925} variant="cross" color={teal} />
        </div>

        <AbsoluteFill style={{ transformOrigin: "960px 540px" }}>
          <mg.CameraRig zoom={zoom} x={panX * zoom} y={panY * zoom}>
            <div style={{ position: "absolute", left: 540, top: 300, width: 840, height: 96, boxSizing: "border-box", overflow: "hidden", borderRadius: 24, background: "linear-gradient(100deg, #EAF3FF 0%, #F9FCFF 45%, #DDEBFF 100%)", border: "1px solid rgba(36,107,253,0.21)", boxShadow: "0 15px 42px rgba(36,107,253,0.17), 0 5px 15px rgba(20,43,60,0.06)", opacity: Math.min(1, laneEntry), transform: "translateY(" + (1 - laneEntry) * 8 + "px)", zIndex: 3 }}>
              <div style={{ position: "absolute", left: 27, top: 15, zIndex: 2, color: ink, fontSize: 26, lineHeight: 1, fontWeight: 500, letterSpacing: 1.5 }}>ATMOSPHERIC WIND</div>
              <div style={{ position: "absolute", right: 27, top: 17, fontFamily: mono, fontSize: 19, color: blue, letterSpacing: 1.5, opacity: 0.8 }}>E → W</div>
              <svg width={840} height={96} viewBox="0 0 840 96" style={{ position: "absolute", inset: 0, overflow: "hidden" }}>
                <path d="M 30 68 C 250 58 573 77 810 64" fill="none" stroke="#246BFD" strokeWidth={2} strokeLinecap="round" opacity={0.13} />
                <g opacity={windStrength}>
                  {Array.from({ length: 7 }, (_, index) => {
                    const x = ((index * 153 - travelTime * 7.5 + 10000) % 1070) - 115;
                    const y = 63 + (index % 3) * 7;
                    return (
                      <g key={index}>
                        <path d={"M " + x + " " + y + " Q " + (x + 47) + " " + (y - 6) + " " + (x + 95) + " " + (y - 2)} fill="none" stroke="#246BFD" strokeWidth={10} strokeLinecap="round" opacity={0.075} />
                        <path d={"M " + x + " " + y + " Q " + (x + 47) + " " + (y - 6) + " " + (x + 95) + " " + (y - 2)} fill="none" stroke="#246BFD" strokeWidth={3.5} strokeLinecap="round" opacity={0.74} />
                      </g>
                    );
                  })}
                </g>
              </svg>
            </div>

            <div style={{ position: "absolute", left: 660, top: 328, width: 600, height: 350, opacity: Math.min(1, cardEntry), transform: "translateY(" + (1 - cardEntry) * 10 + "px)", zIndex: 2 }}>
              <mg.Card width={600} height={350} tilt={-2} mode="dark" style={{ position: "relative", borderRadius: 24, overflow: "hidden", background: "rgba(15,23,42,0.85)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.10)", boxShadow: "0 20px 60px rgba(0,102,255,0.30), 0 8px 24px rgba(0,0,0,0.30)" }}>
                <div style={{ position: "absolute", inset: 0, borderRadius: 24, background: "radial-gradient(ellipse at 50% 50%, rgba(36,107,253,0.21), transparent 67%), linear-gradient(125deg, rgba(255,255,255,0.05), transparent 48%)" }} />
                <div style={{ position: "absolute", inset: 0, transform: "rotate(2deg)", transformOrigin: "300px 175px" }}>
                  <svg width={310} height={310} viewBox="0 0 320 320" style={{ position: "absolute", left: 145, top: 17, overflow: "visible", filter: "drop-shadow(0px 0px 12px rgba(36,107,253,0.32))" }}>
                    <g transform={"rotate(" + rotation + " 160 160)"}>
                      {[0, 120, 240].map((angle) => (
                        <path key={angle} transform={"rotate(" + angle + " 160 160)"} d="M 151 157 C 126 135 121 101 139 70 C 156 40 187 31 212 46 C 230 57 221 78 205 96 C 187 117 177 141 173 160 C 169 174 157 173 151 157 Z" fill="#246BFD" stroke="#5990FF" strokeWidth={2} strokeLinejoin="round" />
                      ))}
                    </g>
                    <path d="M 302 84 C 258 42 206 17 147 21 C 108 24 76 36 50 62" fill="none" stroke="#67A5FF" strokeWidth={5} strokeLinecap="round" strokeDasharray="60 24" strokeDashoffset={-travelTime * 3.5} opacity={0.85 * windStrength} />
                    <path d="M 287 253 C 247 289 193 304 139 297 C 96 292 60 274 27 247" fill="none" stroke="#246BFD" strokeWidth={5} strokeLinecap="round" strokeDasharray="66 26" strokeDashoffset={-travelTime * 3.5} opacity={0.85 * windStrength} />
                    <circle cx={160} cy={160} r={23} fill="#F8FAFC" stroke="#8AB7FF" strokeWidth={5} />
                  </svg>
                  <div style={{ position: "absolute", left: 265, top: 137, width: 70, height: 70, borderRadius: 24, opacity: focusOpacity, transform: "scale(" + (0.93 + 0.07 * Math.min(1.05, focusEntry)) + ")", boxShadow: frame < stopCue ? "0 0 26px rgba(36,107,253,0.27)" : "0 0 26px rgba(242,107,88,0.28)" }}>
                    <mg.FocusFrame color={focusColor} borderRadius={24} style={{ width: 70, height: 70, borderRadius: 24 }}>
                      <div style={{ width: 70, height: 70, borderRadius: 24 }} />
                    </mg.FocusFrame>
                  </div>
                  <div style={{ position: "absolute", left: 28, bottom: 24, width: 187, height: 42, boxSizing: "border-box", borderRadius: 9999, background: frame < stopCue ? "rgba(36,107,253,0.16)" : "rgba(242,107,88,0.16)", border: frame < stopCue ? "1px solid rgba(87,149,255,0.36)" : "1px solid rgba(242,107,88,0.50)", boxShadow: frame < stopCue ? "0 5px 22px rgba(36,107,253,0.23)" : "0 5px 22px rgba(242,107,88,0.27)", display: "flex", alignItems: "center", justifyContent: "center", gap: 10, transform: "scale(" + (1 + 0.025 * Math.max(0, stoppedEntry - 1)) + ")" }}>
                    <span style={{ width: 7, height: 7, borderRadius: 9999, background: statusColor, boxShadow: "0 0 12px " + statusColor }} />
                    <span style={{ color: "#F8FAFC", fontFamily: mono, fontSize: 17, letterSpacing: 1.4 }}>{frame < stopCue ? "FAN ACTIVE" : "FAN STOPPED"}</span>
                  </div>
                </div>
              </mg.Card>
            </div>

            <div style={{ position: "absolute", left: 540, top: 704, width: 840, height: 136, boxSizing: "border-box", overflow: "hidden", borderRadius: 24, background: "linear-gradient(110deg, #E2F5F5 0%, #B7E1E9 47%, #81CAD7 100%)", border: "1px solid rgba(22,143,173,0.35)", boxShadow: "0 18px 48px rgba(22,143,173,0.23), 0 6px 19px rgba(20,43,60,0.07)", opacity: Math.min(1, waterEntry), transform: "translateY(" + (1 - waterEntry) * 8 + "px)", zIndex: 1 }}>
              <div style={{ position: "absolute", inset: 0, borderRadius: 24, background: "linear-gradient(180deg, rgba(255,255,255,0.65) 0%, rgba(255,255,255,0.04) 36%, rgba(22,143,173,0.12) 100%)" }} />
              <svg width={840} height={136} viewBox="0 0 840 136" style={{ position: "absolute", inset: 0 }}>
                <path d={"M -12 26 C 102 " + (15 + Math.sin(frame * 0.024) * 3) + " 184 36 299 25 S 507 15 633 25 S 761 33 855 22"} fill="none" stroke="#FFFFFF" strokeWidth={3} strokeLinecap="round" opacity={0.43 + sheenOpacity} />
                <path d="M 0 105 C 168 89 246 126 416 106 S 665 94 840 109" fill="none" stroke="#168FAD" strokeWidth={22} strokeLinecap="round" opacity={0.06 + 0.05 * cooling} />
                <path d="M 19 33 C 228 9 434 40 811 20" fill="none" stroke="#F5FFFF" strokeWidth={14} strokeLinecap="round" opacity={sheenOpacity} />
              </svg>
              <div style={{ position: "absolute", left: 27, top: 51, fontSize: 26, fontWeight: 500, letterSpacing: 0.7, whiteSpace: "nowrap" }}>
                SURFACE WATER <span style={{ color: teal }}>·</span> <span style={{ color: regionEntry > 0 ? "#0D637D" : ink }}>EASTERN PACIFIC</span>
              </div>
              <div style={{ position: "absolute", left: 27, bottom: 18, fontSize: 19, color: "#155B6D", fontWeight: 500, letterSpacing: 0.2, opacity: cooling * (1 - statusChange) }}>Wind-driven cooling</div>
              <div style={{ position: "absolute", left: 27, bottom: 18, display: "flex", alignItems: "center", gap: 9, fontSize: 19, color: ink, fontWeight: 500, letterSpacing: 0.2, opacity: statusChange }}>
                <span style={{ width: 7, height: 7, borderRadius: 9999, background: "#F26B58", boxShadow: "0 0 12px rgba(242,107,88,0.30)" }} />
                Cooling interrupted
              </div>
              <div style={{ position: "absolute", left: 331, top: 88, width: 303, height: 2, borderRadius: 9999, background: teal, opacity: 0.45 * Math.min(1, regionEntry), transformOrigin: "left center", transform: "scaleX(" + Math.min(1, regionEntry) + ")" }} />
            </div>
          </mg.CameraRig>
        </AbsoluteFill>

        <AbsoluteFill style={{ pointerEvents: "none", zIndex: 20 }}>
          <mg.Noise opacity={0.035} />
        </AbsoluteFill>
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = {
  index?: number;
  wordIndex?: number;
  startFrame?: number;
  word?: string;
  text?: string;
};

type ShotProps = {
  wordCues?: WordCue[];
};

const BLUE = "#246BFD";
const TEAL = "#168FAD";
const WHITE = "#F8FAFC";
const MUTED = "#AAC2DB";
const SHADOW = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.4)";
const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const SMOOTH = { ...CLAMP, easing: Easing.inOut(Easing.cubic) };
const FONT = "Inter, Arial, sans-serif";
const HEAD = "Manrope, Inter, Arial, sans-serif";

const glass: React.CSSProperties = {
  borderRadius: 24,
  overflow: "hidden",
  background: "rgba(15,23,42,0.85)",
  backdropFilter: "blur(14px)",
  border: "1px solid rgba(255,255,255,0.10)",
  boxShadow: SHADOW,
  boxSizing: "border-box"
};

const RoundedArrow: React.FC<{ x: number; y: number; opacity: number }> = ({ x, y, opacity }) => (
  <svg width={64} height={30} viewBox="0 0 64 30" style={{ position: "absolute", left: x, top: y, opacity, overflow: "visible" }}>
    <path d="M 58 15 L 8 15 M 20 4 L 8 15 L 20 26" fill="none" stroke={BLUE} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" filter="url(#mgGlow)" />
  </svg>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const f = Math.min(frame, durationInFrames - 1);

  const cueAt = (index: number, fallback: number): number => {
    const explicit = cues.find((cue) => cue.wordIndex === index || cue.index === index);
    const positional = cues.length === 38 ? cues[index - 23] : undefined;
    const selected = explicit || positional;
    return typeof selected?.startFrame === "number" ? selected.startFrame : fallback;
  };

  const elAt = cueAt(25, 25);
  const ninoAt = cueAt(26, 40);
  const superAt = cueAt(35, 170);
  const secondElAt = cueAt(36, 185);
  const secondNinoAt = cueAt(37, 200);
  const explainAt = cueAt(38, 233);
  const actuallyAt = cueAt(44, 322);
  const steadyAt = cueAt(48, 381);
  const windsAt = cueAt(49, 396);
  const tradeAt = cueAt(53, 456);
  const tradeWindsAt = cueAt(54, 470);
  const blowAt = cueAt(56, 500);
  const eastAt = cueAt(58, 530);
  const westAt = cueAt(60, 559);

  const enter = (at: number) => spring({
    frame: Math.max(0, f - at),
    fps,
    config: { damping: 14, stiffness: 160, mass: 0.8 }
  });
  const reveal = (at: number, length = 14) => interpolate(f, [at, at + length], [0, 1], CLAMP);
  const openEnd = actuallyAt + 16;
  const opening = interpolate(f, [explainAt, openEnd], [0, 1], SMOOTH);
  const laneReveal = interpolate(opening, [0.38, 1], [0, 1], CLAMP);
  const windReveal = reveal(steadyAt, 20);
  const flow = Math.max(0, f - steadyAt);
  const breath = 0.5 + 0.5 * Math.sin(f / 47);

  const zoom = interpolate(
    f,
    [0, secondNinoAt + 15, explainAt - 1, openEnd, steadyAt, tradeWindsAt + 16, 547, 575, 607],
    [1, 1.025, 1.025, 1, 1, 1.18, 1.18, 1, 1],
    SMOOTH
  );
  const panX = interpolate(f, [0, blowAt, 546, 547, 575, 607], [0, 0, 50, 50, 0, 0], SMOOTH);
  const headingIn = enter(2);
  const headingOpacity = reveal(2, 12);
  const queryExit = 1 - interpolate(f, [explainAt + 5, explainAt + 45], [0, 1], SMOOTH);
  const queryCount = f < elAt ? 0 : f < ninoAt ? Math.min(3, 1 + Math.floor((f - elAt) / 5)) : Math.min(7, 4 + Math.floor((f - ninoAt) / 3));
  const queryText = "El Niño".slice(0, queryCount);
  const cursorOpacity = queryCount < 7 || f < 72 ? 0.5 + 0.5 * Math.sin(f / 4) : 0;

  const evidenceLeft = interpolate(opening, [0, 1], [260, 300]);
  const evidenceWidth = interpolate(opening, [0, 1], [1400, 1320]);
  const evidenceHeight = interpolate(opening, [0, 1], [104, 68]);
  const labelWidth = interpolate(opening, [0, 1], [380, 346]);
  const valueSize = interpolate(opening, [0, 1], [40, 31]);
  const mechanismX = interpolate(opening, [0, 1], [260, 340]);
  const mechanismY = interpolate(opening, [0, 1], [572, 510]);
  const mechanismW = interpolate(opening, [0, 1], [1400, 1240]);
  const mechanismH = interpolate(opening, [0, 1], [104, 210]);
  const mechanismIn = enter(ninoAt + 10);
  const leadX = 1490 - flow * 2.38;
  const focusIn = enter(tradeAt);
  const focusOpacity = reveal(tradeAt, 14) * (1 - interpolate(f, [575, 594], [0, 1], CLAMP));
  const leadOpacity = windReveal * interpolate(leadX, [420, 455, 1470, 1520], [0, 1, 1, 0], CLAMP);
  const eastPulse = reveal(eastAt, 9);
  const westPulse = reveal(westAt, 9);

  const evidenceCard = (label: string, value: string, initialY: number, finalY: number, at: number, valueAt: number, accent: string) => {
    const arrival = enter(at);
    const opacity = reveal(at, 14);
    const textOpacity = reveal(valueAt, 12);
    return (
      <div key={label} style={{
        ...glass,
        position: "absolute",
        left: evidenceLeft,
        top: interpolate(opening, [0, 1], [initialY, finalY]),
        width: evidenceWidth,
        height: evidenceHeight,
        opacity,
        transform: "translateY(" + ((1 - arrival) * 20) + "px)",
        display: "flex",
        alignItems: "center",
        padding: "0 34px",
        background: "linear-gradient(105deg, rgba(22,42,67,0.95), rgba(12,27,47,0.89))"
      }}>
        <div style={{ position: "absolute", left: 0, top: 20, bottom: 20, width: 4, borderRadius: 9999, background: accent, boxShadow: "0 0 22px " + accent }} />
        <div style={{ width: labelWidth, flexShrink: 0, color: MUTED, fontSize: 26, fontWeight: 500, whiteSpace: "nowrap" }}>{label}</div>
        <div style={{ color: WHITE, fontSize: valueSize, lineHeight: 1.1, fontFamily: HEAD, fontWeight: 600, opacity: textOpacity, transform: "translateY(" + ((1 - enter(valueAt)) * 9) + "px)", whiteSpace: "nowrap" }}>{value}</div>
        <div style={{ marginLeft: "auto", width: 9, height: 9, borderRadius: 9999, background: accent, opacity: textOpacity * 0.85, boxShadow: "0 0 18px " + accent }} />
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ overflow: "hidden", background: "#0B1727" }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080, transform: "scale(" + (width / 1920) + "," + (height / 1080) + ")", transformOrigin: "0 0", fontFamily: FONT, color: WHITE }}>
        <AbsoluteFill style={{ borderRadius: 24, background: "linear-gradient(155deg, #070E1B 0%, #0B1727 36%, #10243B 70%, #080F1D 100%)" }} />
        <AbsoluteFill style={{ opacity: 0.23, borderRadius: 24, overflow: "hidden" }}>
          <mg.GridBackground mode="dark" gridSize={48} />
        </AbsoluteFill>
        <AbsoluteFill style={{ borderRadius: 24, background: "radial-gradient(62% 76% at " + (66 + Math.sin(f / 150) * 3) + "% 35%, rgba(0,102,255," + (0.17 + breath * 0.025) + "), transparent 72%), radial-gradient(45% 55% at 15% 85%, rgba(22,143,173,0.13), transparent 74%)" }} />

        <svg width={1} height={1} style={{ position: "absolute", left: 0, top: 0, pointerEvents: "none" }}>
          <defs>
            <filter id="mgGlow" x="-100%" y="-150%" width="300%" height="400%">
              <feGaussianBlur stdDeviation={4} result="glow" />
              <feMerge><feMergeNode in="glow" /><feMergeNode in="SourceGraphic" /></feMerge>
            </filter>
            <filter id="mgSoft" x="-80%" y="-160%" width="260%" height="420%">
              <feGaussianBlur stdDeviation={10} />
            </filter>
          </defs>
        </svg>

        <div style={{ position: "absolute", inset: 0, borderRadius: 24, pointerEvents: "none" }}>
          <div style={{ position: "absolute", inset: 0, transform: "translateY(75px)", borderRadius: 24 }}>
            <mg.CameraRig zoom={zoom} x={panX} y={0}>
              <div style={{ position: "absolute", left: 0, top: -75, width: 1920, height: 1080, borderRadius: 24 }}>
