import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; id?: string | number; word?: string; text?: string; startFrame?: number; };
type ShotProps = { wordCues?: WordCue[]; };

const C = {
  ink: '#142B3C', ivory: '#F8FAFC', blue: '#246BFD',
  coral: '#FF5A36', emerald: '#10B981', teal: '#0EA5A4', amber: '#F59E0B',
};

const GlassNode = ({ x, y, lines, accent, rgb, category, active = 0, established = false, scale = 1 }: {
  x: number; y: number; lines: string[]; accent: string; rgb: string;
  category: string; active?: number; established?: boolean; scale?: number;
}) => (
  <div style={{
    position: 'absolute', left: x, top: y, width: 540, height: 142,
    boxSizing: 'border-box', borderRadius: 24, transform: 'scale(' + scale + ')',
    transformOrigin: '50% 50%', background: 'rgba(15,23,42,0.85)',
    backdropFilter: 'blur(14px)', border: '1px solid rgba(255,255,255,0.10)',
    boxShadow: '0 20px 60px rgba(' + rgb + ',' + (established ? 0.16 : 0.18 + active * 0.12) + '), 0 8px 24px rgba(0,0,0,0.22)',
  }}>
    <div style={{ position: 'absolute', inset: 0, borderRadius: 24, background: 'radial-gradient(ellipse at 100% 0%, rgba(' + rgb + ',' + (0.035 + active * 0.16) + '), transparent 72%)' }} />
    <div style={{ position: 'absolute', left: 0, top: 22, bottom: 22, width: 5, borderRadius: 9999, background: accent, opacity: established ? 0.8 : 0.55 + active * 0.45, boxShadow: '0 0 ' + (8 + active * 12) + 'px rgba(' + rgb + ',0.35)' }} />
    <div style={{ position: 'absolute', left: 30, top: 15, fontFamily: 'Inter, sans-serif', fontSize: 13, lineHeight: '19px', fontWeight: 500, letterSpacing: 1.8, color: accent, opacity: established ? 0.78 : 0.7 + active * 0.3 }}>{category}</div>
    <div style={{ position: 'absolute', left: 30, right: 22, top: 38, bottom: 13, display: 'flex', flexDirection: 'column', justifyContent: 'center', fontFamily: 'Inter, sans-serif', fontSize: 31, lineHeight: '38px', letterSpacing: -0.6, fontWeight: 500, color: C.ivory, opacity: established ? 0.9 : 0.94 }}>
      {lines.map((line, i) => <div key={i} style={{ whiteSpace: 'nowrap' }}>{line}</div>)}
    </div>
    <div style={{ position: 'absolute', left: 24, right: 24, top: 0, height: 1, borderRadius: 9999, background: 'linear-gradient(90deg, transparent, rgba(' + rgb + ',' + (0.08 + active * 0.34) + '), transparent)' }} />
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueAt = (index: number, fallback: number) => {
    const cue = cues.find((item) => item.wordIndex === index || item.index === index || item.id === index || item.id === 'W' + index);
    return cue && typeof cue.startFrame === 'number' && Number.isFinite(cue.startFrame) ? cue.startFrame : fallback;
  };
  const offAt = cueAt(87, 0);
  const peruAt = cueAt(91, 64);
  const ecuadorAt = cueAt(94, 115);
  const waterLeadAt = cueAt(95, 132);
