  const climateAt = cueAt(103, 268);
  const dryAt = cueAt(104, 285);
  const progress = (start: number, length: number) => interpolate(frame, [start, start + length], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const settle = (start: number) => frame < start ? 0 : spring({ frame: frame - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const endFrame = Math.max(270, durationInFrames - 1);
