  const panY = interpolate(cameraTime, [0, waterLeadAt, helpingAt, 269, 332], [25, 10, -20, 0, 0], cameraOptions);
  const intro = progress(offAt, 18);
  const placeActive = (0.24 + intro * 0.16 + progress(peruAt, 15) * 0.40 + progress(ecuadorAt, 13) * 0.20) * (1 - progress(waterLeadAt, 55) * 0.64);
  const coldActive = Math.min(1, progress(waterAt, 20) * 0.34 + Math.max(0, settle(coldAt)) * 0.66);
  const dryActive = Math.min(1, progress(climateAt, 16) * 0.28 + Math.max(0, settle(dryAt)) * 0.72);
