export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const lastFrame = Math.max(691, durationInFrames - 1);

  const cueAt = (index: number, fallback: number, word: string) => {
    const indexed = cues.find((cue) => cue.wordIndex === index || cue.index === index);
    if (indexed && typeof indexed.startFrame === "number") return indexed.startFrame;
    const matched = cues.find((cue) => {
      const value = String(cue.word || cue.text || "").toLowerCase().replace(/[^a-z]/g, "");
      return value === word;
    });
    return matched && typeof matched.startFrame === "number" ? matched.startFrame : fallback;
  };

  const worldAt = cueAt(144, 169, "world");
