  const indonesiaAt = cueAt(167, 599, "indonesia");
  const australiaAt = cueAt(169, 635, "australia");
  const droughtAt = cueAt(171, 671, "drought");
  const wideAt = Math.max(140, worldAt + 17);

  const ramp = (start: number, length: number) => interpolate(frame, [start, start + length], [0, 1], smooth);
  const pop = (start: number) => frame < start ? 0 : spring({ frame: frame - start, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const zoom = interpolate(frame, [0, 45, 139, wideAt], [1.2, 1.2, 1.04, 1], clamp);
  const panX = interpolate(frame, [0, wideAt, 201, 690, lastFrame], [0, 0, -6, 6, 0], smooth);
  const panY = 0;
  const dossierShift = interpolate(frame, [690, lastFrame], [0, 12], smooth);
  const sourceEntry = pop(2);
  const sourceOpacity = ramp(2, 12);
  const stageOpacity = ramp(64, 26);
  const markerOpacity = ramp(128, 30);
  const backgroundDrift = interpolate(frame, [0, lastFrame], [0, 18], clamp);
  const sourcePivotY = (540 - 267) * (zoom - 1);

  const canadaProgress = ramp(warmerAt, 34);
  const rainProgress = ramp(heavierAt, 35);
  const rainDensity = ramp(rainAt, 30);
  const floodProgress = ramp(floodingAt, 40);
  const dryProgress = ramp(droughtAt, 19);
  const dryPreview = 0.08 * ramp(indonesiaAt, 22) + 0.09 * ramp(australiaAt, 20);
  const dryness = Math.min(1, dryPreview + dryProgress * 0.83);

  const focusRect = (r: Region) => ({ x: r.x - 6, y: r.y - 6, width: r.width + 12, height: r.height + 12 });
  const canadaRegion = regions[1];
  const rainRegion = regions[3];
  const floodRegion = regions[0];
  const droughtRegion = regions[2];
  const mixRect = (a: Region, b: Region, t: number) => {
    const start = focusRect(a);
    const end = focusRect(b);
    return {
      x: start.x + (end.x - start.x) * t,
      y: start.y + (end.y - start.y) * t,
      width: start.width + (end.width - start.width) * t,
      height: start.height + (end.height - start.height) * t
    };
  };
  let focus = focusRect(canadaRegion);
  let travelOpacity = 1;
  if (frame >= indonesiaAt) {
    const t = ramp(indonesiaAt, 18);
    focus = mixRect(floodRegion, droughtRegion, t);
    travelOpacity = 1 - Math.sin(t * Math.PI) * 0.45;
  } else if (frame >= floodingAt) {
    const t = ramp(floodingAt, 22);
    focus = mixRect(rainRegion, floodRegion, t);
    travelOpacity = 1 - Math.sin(t * Math.PI) * 0.72;
  } else if (frame >= heavierAt) {
    const t = ramp(heavierAt, 18);
    focus = mixRect(canadaRegion, rainRegion, t);
    travelOpacity = 1 - Math.sin(t * Math.PI) * 0.45;
  }
  const focusOpacity = ramp(warmerAt, 10) * travelOpacity;
  const focusScale = frame < heavierAt ? 0.987 + pop(warmerAt) * 0.013 : 1;

  const renderIndicator = (region: Region) => {
    if (region.id === "canada") {
      return (
        <div style={{ position: "absolute", left: 30, right: 30, top: 128, height: 108, borderRadius: 24, overflow: "hidden", background: "rgba(248,250,252,0.025)", border: "1px solid rgba(248,250,252,0.035)" }}>
          <div style={{ position: "absolute", left: 23, right: 23, top: 67, height: 27, borderRadius: 9999, border: "1px solid rgba(248,250,252,0.17)", background: "rgba(248,250,252,0.035)" }} />
          <div style={{ position: "absolute", inset: 0, borderRadius: 24, opacity: canadaProgress, background: "radial-gradient(ellipse at 55% 32%, rgba(255,90,54,0.24), transparent 72%)" }} />
          <div style={{ position: "absolute", left: 23, right: 23, top: 67 - 43 * canadaProgress, height: 27, borderRadius: 9999, opacity: 0.12 + 0.88 * canadaProgress, background: "linear-gradient(90deg, #F26B58 0%, #FF5A36 55%, #F79A80 100%)", boxShadow: "0 12px 30px rgba(255,90,54,0.28)", transform: "rotate(" + (-0.55 * canadaProgress) + "deg)" }} />
