    if (region.id === "rain") {
      const rainClock = Math.max(0, frame - rainAt);
      return (
        <div style={{ position: "absolute", left: 30, right: 30, top: 128, height: 122, borderRadius: 24, overflow: "hidden", background: "linear-gradient(180deg, rgba(16,185,129,0.025), rgba(16,185,129,0.075))", border: "1px solid rgba(248,250,252,0.035)" }}>
          <div style={{ position: "absolute", inset: 0, borderRadius: 24, opacity: rainProgress, background: "radial-gradient(ellipse at 50% 80%, rgba(16,185,129,0.17), transparent 78%)" }} />
          {Array.from({ length: 22 }, (_, i) => {
            const established = i % 3 === 0;
            const visibility = established ? 0.16 + 0.77 * rainProgress : 0.88 * rainDensity;
            const y = ((i * 31 + rainClock * 1.24) % 177) - 52;
            const dropHeight = 29 + (i % 4) * 7;
            return <div key={i} style={{ position: "absolute", left: 25 + i * 29, top: y, width: 10, height: dropHeight, borderRadius: 9999, opacity: visibility, background: "linear-gradient(180deg, rgba(16,185,129,0.12), #10B981)", boxShadow: "0 5px 14px rgba(16,185,129,0.24)" }} />;
          })}
        </div>
      );
    }
    if (region.id === "southAmerica") {
      const waterHeight = 18 + 62 * floodProgress;
      return (
        <div style={{ position: "absolute", left: 30, right: 30, top: 128, height: 108, borderRadius: 24, overflow: "hidden", background: "linear-gradient(180deg, rgba(22,143,173,0.025), rgba(22,143,173,0.11))", border: "1px solid rgba(248,250,252,0.055)" }}>
          <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: waterHeight, borderRadius: 24, opacity: 0.18 + floodProgress * 0.82, background: "linear-gradient(180deg, #168FAD 0%, #136C85 100%)", boxShadow: "0 -8px 28px rgba(20,184,166,0.22)" }} />
          <div style={{ position: "absolute", left: 9, right: 9, bottom: waterHeight - 4, height: 4, borderRadius: 9999, background: "linear-gradient(90deg, rgba(16,185,129,0.22), #10B981 32%, #10B981 68%, rgba(16,185,129,0.22))", opacity: 0.14 + floodProgress * 0.86, boxShadow: "0 0 18px rgba(16,185,129,0.30)" }} />
          <div style={{ position: "absolute", left: 36, right: 36, bottom: 12, height: 2, borderRadius: 9999, background: "rgba(203,242,246,0.18)", opacity: floodProgress }} />
        </div>
      );
    }
    return (
      <div style={{ position: "absolute", left: 30, right: 30, top: 128, height: 122, borderRadius: 24, overflow: "hidden", background: "rgba(248,250,252,0.024)", border: "1px solid rgba(248,250,252,0.035)" }}>
        <div style={{ position: "absolute", inset: 0, borderRadius: 24, opacity: 0.13 + dryness * 0.87, background: "radial-gradient(ellipse at 51% 60%, rgba(245,158,11,0.39) 0%, rgba(216,155,41,0.15) 45%, transparent 76%)", transform: "scaleX(" + (0.38 + 0.62 * dryness) + ")" }} />
        {Array.from({ length: 12 }, (_, i) => (
          <div key={i} style={{ position: "absolute", left: 41 + i * 52, top: 15 + (i % 3) * 13 + dryProgress * 17, width: 9, height: 33 - dryProgress * 24, borderRadius: 9999, opacity: (0.31 + (i % 2) * 0.12) * (1 - dryProgress), background: "linear-gradient(180deg, rgba(16,185,129,0.16), #16866D)", boxShadow: "0 4px 14px rgba(16,185,129,0.08)" }} />
        ))}
        <div style={{ position: "absolute", left: "50%", top: 57, width: 140 + 450 * dryness, height: 39, borderRadius: 9999, transform: "translateX(-50%)", opacity: 0.07 + dryness * 0.88, background: "linear-gradient(90deg, rgba(216,155,41,0.10), #D89B29 24%, #F59E0B 55%, rgba(216,155,41,0.12))", boxShadow: "0 12px 32px rgba(245,158,11,0.24)" }} />
      </div>
    );
  };

  const renderSlab = (region: Region) => {
    const entry = pop(region.enter);
    const entryOpacity = ramp(region.enter, 14);
    const activation = region.id === "canada" ? canadaProgress : region.id === "rain" ? rainProgress : region.id === "southAmerica" ? floodProgress : dryProgress;
    const activeAt = region.id === "canada" ? warmerAt : region.id === "rain" ? heavierAt : region.id === "southAmerica" ? floodingAt : droughtAt;
    const namedAt = region.id === "canada" ? canadaAt : region.id === "rain" ? statesAt : region.id === "southAmerica" ? americaAt : australiaAt;
    const namedPulse = interpolate(frame, [namedAt, namedAt + 8, namedAt + 30], [0, 1, 0], clamp);
    const titleEmphasis = region.id === "drought" ? Math.max(dryProgress, ramp(indonesiaAt, 16) * 0.65) : activation;
