        <div style={{ position: "absolute", left: 30, top: 67, fontFamily: "Manrope, Inter, sans-serif", fontSize: 42, lineHeight: "52px", fontWeight: 600, letterSpacing: -1.2, color: region.accent, opacity: activation, transform: "translateY(" + resultRise + "px)", textShadow: "0 3px 24px " + region.glow }}>{region.result}</div>
        {renderIndicator(region)}
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ background: C.porcelain, overflow: "hidden", fontFamily: "Inter, sans-serif" }}>
      <AbsoluteFill style={{ background: "linear-gradient(154deg, #F4F6F2 0%, #F7F8F4 30%, #E4EEF4 71%, #F4F6F2 100%)" }} />
      <AbsoluteFill style={{ opacity: 0.24 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
      <AbsoluteFill style={{ background: "radial-gradient(65% 85% at 76% 27%, rgba(22,143,173,0.12), transparent 71%), radial-gradient(48% 62% at 18% 72%, rgba(255,90,54,0.065), transparent 73%)", transform: "translateX(" + backgroundDrift + "px)" }} />
      <div style={{ position: "absolute", left: 600, top: 130, width: 720, height: 280, borderRadius: 9999, background: "radial-gradient(ellipse, rgba(255,255,255,0.80), rgba(255,255,255,0) 70%)" }} />

      <div style={{ position: "absolute", left: 112, top: 82, zIndex: 5, opacity: ramp(2, 16), transform: "translateY(" + (7 * (1 - Math.min(1, pop(2)))) + "px)" }}>
        <div style={{ color: C.ink, fontFamily: "Manrope, Inter, sans-serif", fontSize: 50, fontWeight: 600, lineHeight: "61px", letterSpacing: -1.8, whiteSpace: "nowrap" }}>One ocean, different consequences</div>
        <div style={{ marginTop: 10, color: C.ink, opacity: 0.65, fontFamily: "Inter, sans-serif", fontSize: 24, fontWeight: 500, lineHeight: "30px", letterSpacing: 3.4 }}>REGIONAL IMPACT DOSSIER</div>
      </div>

      <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080, transform: "scale(" + (width / 1920) + ", " + (height / 1080) + ")", transformOrigin: "0 0" }}>
        <div style={{ position: "absolute", inset: 0, transform: "translateY(" + sourcePivotY + "px)" }}>
          <mg.CameraRig zoom={zoom} x={panX} y={panY}>
            <div style={{ position: "absolute", inset: 0, transform: "translateX(" + dossierShift + "px)" }}>
              <div style={{ position: "absolute", left: 100, top: 198, width: 1720, height: 786, borderRadius: 24, opacity: stageOpacity, background: "linear-gradient(145deg, rgba(255,255,255,0.25), rgba(228,238,244,0.18))", border: "1px solid rgba(255,255,255,0.43)", boxSizing: "border-box" }} />
              <div style={{ position: "absolute", left: 118, top: 248, height: 48, padding: "0 20px", display: "flex", alignItems: "center", borderRadius: 9999, color: C.ink, background: "rgba(255,255,255,0.75)", backdropFilter: "blur(14px)", border: "1px solid rgba(20,43,60,0.08)", boxShadow: "0 8px 24px rgba(22,143,173,0.08)", fontSize: 26, fontWeight: 500, opacity: stageOpacity }}>Possible regional effects</div>
              <div style={{ position: "absolute", left: 1460, top: 258, width: 332, textAlign: "right", fontSize: 24, lineHeight: "30px", color: C.ink, opacity: stageOpacity * 0.62 }}>Qualitative indicators</div>

              <div style={{ position: "absolute", inset: 0, opacity: ramp(74, 38), pointerEvents: "none" }}>
                <div style={{ position: "absolute", left: 959, top: 292, width: 2, height: 44, borderRadius: 9999, background: "rgba(20,43,60,0.23)" }} />
                <div style={{ position: "absolute", left: 490, top: 335, width: 940, height: 2, borderRadius: 9999, background: "rgba(20,43,60,0.23)" }} />
                <div style={{ position: "absolute", left: 489, top: 335, width: 2, height: 26, borderRadius: 9999, background: "rgba(20,43,60,0.23)" }} />
                <div style={{ position: "absolute", left: 1429, top: 335, width: 2, height: 26, borderRadius: 9999, background: "rgba(20,43,60,0.23)" }} />
                <div style={{ position: "absolute", left: 959, top: 335, width: 2, height: 460, borderRadius: 9999, background: "rgba(20,43,60,0.20)" }} />
                <div style={{ position: "absolute", left: 854, top: 794, width: 212, height: 2, borderRadius: 9999, background: "rgba(20,43,60,0.20)" }} />
              </div>

              {regions.map(renderSlab)}

              <div style={{ position: "absolute", left: 860, top: 238, width: 200, height: 58, boxSizing: "border-box", borderRadius: 24, background: "rgba(255,255,255,0.82)", border: "1px solid rgba(20,43,60,0.10)", backdropFilter: "blur(14px)", boxShadow: "0 18px 48px rgba(255,90,54,0.25), 0 6px 18px rgba(20,43,60,0.09)", display: "flex", alignItems: "center", justifyContent: "center", color: C.ink, fontSize: 29, fontWeight: 600, fontFamily: "Manrope, Inter, sans-serif", overflow: "hidden", opacity: sourceOpacity, transform: "translateY(" + (12 * (1 - sourceEntry)) + "px) scale(" + (0.94 + sourceEntry * 0.06) + ")", transformOrigin: "50% 50%" }}>
                <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 5, borderRadius: 9999, background: "linear-gradient(90deg, #F26B58, #FF5A36, #F26B58)" }} />
                <span style={{ paddingTop: 3 }}>El Niño</span>
              </div>

              {frame >= warmerAt && (
                <div style={{ position: "absolute", left: focus.x, top: focus.y, width: focus.width, height: focus.height, borderRadius: 24, opacity: focusOpacity, transform: "scale(" + focusScale + ")", pointerEvents: "none", zIndex: 4 }}>
                  <mg.FocusFrame color={C.coral} borderRadius={24}>
                    <div style={{ position: "relative", width: focus.width, height: focus.height, borderRadius: 24, boxSizing: "border-box", border: "2px solid rgba(255,90,54,0.63)", boxShadow: "0 0 24px rgba(255,90,54,0.10), inset 0 0 15px rgba(255,90,54,0.035)" }} />
                  </mg.FocusFrame>
                </div>
              )}
            </div>
          </mg.CameraRig>
        </div>
      </div>

      <AbsoluteFill style={{ pointerEvents: "none", opacity: markerOpacity * 0.48 }}>
        <mg.Marker x={112} y={216} variant="cross" color={C.teal} />
        <mg.Marker x={1808} y={216} variant="cross" color={C.coral} />
        <mg.Marker x={112} y={976} variant="cross" color={C.teal} />
      </AbsoluteFill>
      <AbsoluteFill style={{ pointerEvents: "none" }}><mg.Noise opacity={0.035} /></AbsoluteFill>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; startFrame?: number; endFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };

const BLUE = "#246BFD";
const CORAL = "#FF5A36";
const INK = "#142B3C";
const WHITE = "#F8FAFC";
const ease = Easing.inOut(Easing.cubic);
const uiFont = "Inter, Arial, sans-serif";
const monoFont = "IBM Plex Mono, Consolas, monospace";
const blueShadow = "0 20px 60px rgba(0,102,255,0.25), 0 8px 24px rgba(0,0,0,0.14)";
const glass: React.CSSProperties = { position: "absolute", borderRadius: 24, background: "rgba(15,23,42,0.85)", backdropFilter: "blur(14px)", border: "1px solid rgba(255,255,255,0.10)", boxSizing: "border-box", color: WHITE };

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const t = Math.min(frame, durationInFrames - 1);
  const cueAt = (id: number, fallback: number) => {
    const byId = cues.find((cue) => cue.wordIndex === id || cue.index === id);
    const local = cues.length === 27 ? cues[id - 172] : undefined;
    const start = (byId || local)?.startFrame;
    return typeof start === "number" && Number.isFinite(start) ? start : fallback;
  };
  const range = (a: number, b: number, from = 0, to = 1) => interpolate(t, [a, b], [from, to], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  const enter = (at: number) => t < at ? 0 : spring({ frame: t - at, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const opacityAt = (at: number, length = 12) => range(at, at + length);

  const yearAt = Math.max(26, cueAt(174, 26));
  const powerfulAt = cueAt(176, 56);
  const elAt = cueAt(177, 71);
  const ninoAt = cueAt(178, 85);
  const oneAt = cueAt(180, 115);
  const ofAt = cueAt(181, 130);
  const theAt = cueAt(182, 145);
  const factorsAt = cueAt(183, 160);
  const famineAt = cueAt(186, 205);
  const estimatedAt = cueAt(193, 309);
  const threeAt = cueAt(194, 324);

  const cameraTimes = [0, 26, 72, 115, 176, 191, 205, 281, 355, 356, 400, 437];
  const cameraValue = (values: number[]) => interpolate(t, cameraTimes, values, { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  const zoom = cameraValue([1, 1, 1.05, 1.05, 1.08, 1.08, 1.08, 1.18, 1.18, 1.18, 1, 1]);
  const panX = cameraValue([0, 0, -10, -10, 0, 0, 0, -70, -70, -70, 0, 0]);
  const panY = cameraValue([0, 0, -10, -10, -35, -35, -35, -70, -70, -70, 0, 0]);
  const rigX = (zoom - 1) * 960 + zoom * panX;
  const rigY = (zoom - 1) * 540 + zoom * panY;
  const shell = enter(3);
  const shellOpacity = opacityAt(3, 14);
  const shellY = 14 * (1 - shell);
  const titleOpacity = opacityAt(yearAt, 14);
  const matrixAt = famineAt + 13;
  const matrixOpacity = opacityAt(matrixAt, 18);
  const coralProgress = range(threeAt, threeAt + 14);
  const qualifierOpacity = opacityAt(estimatedAt, 12);
  const stageScale = Math.min(width / 1920, height / 1080);

  const bracketStart = { left: 251, top: 447, width: 638, height: 114 };
  const bracketMiddle = { left: 251, top: 579, width: 638, height: 114 };
  const bracketEnd = { left: 986, top: 304, width: 506, height: 505 };
  const qualifierTravel = range(oneAt, factorsAt + 16);
  const populationTravel = range(famineAt, 281);
  const blend = (a: number, b: number, p: number) => a + (b - a) * p;
  const bracketMetric = (key: keyof typeof bracketStart) => blend(blend(bracketStart[key], bracketMiddle[key], qualifierTravel), bracketEnd[key], populationTravel);
  const bracketOpacity = opacityAt(powerfulAt, 10);
  const bracketColor = t < threeAt ? BLUE : `rgb(${Math.round(blend(36, 255, coralProgress))}, ${Math.round(blend(107, 90, coralProgress))}, ${Math.round(blend(253, 54, coralProgress))})`;

  const regions = [
    { label: "Canada", color: "#D89B29" },
    { label: "Southern United States", color: "#16866D" },
    { label: "Parts of South America", color: "#16866D" },
    { label: "Indonesia and Australia", color: "#D89B29" }
  ];
  const drawerProgress = range(0, 24);
  const rowStyle = (top: number): React.CSSProperties => ({ position: "absolute", left: 32, top, width: 614, height: 90, borderRadius: 22, background: "rgba(255,255,255,0.045)", border: "1px solid rgba(255,255,255,0.10)", boxSizing: "border-box", display: "flex", alignItems: "center", padding: "0 28px" });
  const spokenWord = (word: string, at: number) => (
    <span key={word + at} style={{ display: "inline-block", opacity: opacityAt(at, 9), transform: `translateY(${6 * (1 - enter(at))}px)`, marginRight: 9 }}>{word}</span>
  );

  return (
    <AbsoluteFill style={{ background: "#F4F6F2", fontFamily: uiFont }}>
      <div style={{ position: "absolute", left: (width - 1920 * stageScale) / 2, top: (height - 1080 * stageScale) / 2, width: 1920, height: 1080, transform: `scale(${stageScale})`, transformOrigin: "top left", color: INK }}>
        <AbsoluteFill style={{ background: "linear-gradient(155deg, #FBFCF7 0%, #F4F6F2 29%, #E4EEF4 67%, #F7F9F4 100%)" }} />

        <AbsoluteFill style={{ overflow: "hidden", borderRadius: 24, pointerEvents: "none" }}>
          <div style={{ position: "absolute", inset: -48, opacity: 0.18, transform: `translate(${range(0, 437, 0, 12)}px, ${range(0, 437, 0, 6)}px)` }}>
            <mg.GridBackground mode="light" gridSize={48} />
          </div>
          <AbsoluteFill style={{ background: "radial-gradient(66% 75% at 72% 25%, rgba(36,107,253,0.13), transparent 72%), radial-gradient(45% 50% at 23% 78%, rgba(255,90,54,0.075), transparent 75%)" }} />
          <div style={{ position: "absolute", left: 100, top: 198, width: 1720, height: 786, borderRadius: 28, background: "linear-gradient(125deg, rgba(255,255,255,0.60), rgba(228,238,244,0.42) 56%, rgba(255,255,255,0.67))", border: "1px solid rgba(20,43,60,0.085)", boxShadow: "inset 0 1px 0 rgba(255,255,255,0.95), 0 24px 80px rgba(36,107,253,0.055)" }} />
          <mg.Marker x={137} y={245} variant="cross" color={BLUE} />
          <mg.Marker x={1782} y={943} variant="cross" color="#16866D" />
        </AbsoluteFill>

        <div style={{ position: "absolute", left: 120, top: 88, opacity: titleOpacity, transform: `translateY(${5 * (1 - enter(yearAt))}px)`, zIndex: 5 }}>
          <div style={{ fontFamily: uiFont, fontSize: 25, fontWeight: 500, lineHeight: 1.25, letterSpacing: 0.25, color: INK }}>Historical case · contributing factor</div>
          <div style={{ fontFamily: "Manrope, Inter, Arial, sans-serif", fontSize: 50, fontWeight: 600, lineHeight: 1.12, letterSpacing: -1.5, marginTop: 7, whiteSpace: "nowrap" }}>The 1870s famine</div>
        </div>

        <mg.CameraRig zoom={zoom} x={rigX} y={rigY}>
          <div style={{ position: "absolute", left: 0, top: 0, width: 1920, height: 1080, transform: `translateY(${shellY}px)`, opacity: shellOpacity }}>
            <div style={{ ...glass, left: 230, top: 280, width: 680, height: 610, boxShadow: blueShadow }}>
              <div style={{ position: "absolute", inset: 0, borderRadius: 24, pointerEvents: "none", background: "radial-gradient(95% 85% at 8% 0%, rgba(36,107,253,0.18), transparent 70%)" }} />
